/** Capture one real search response generated by the authenticated EBSCO nursing page. */
export async function ebscoNursingResponse(tab,query,submitSearch,limit=5){

 if(typeof query!=='string'||!query.trim()||query.length>100||(submitSearch!==undefined&&typeof submitSearch!=='function')||!Number.isInteger(limit)||limit<1||limit>10)throw Error('需要关键词、可选检索回调和1–10条上限');
 const q=query.trim(),c=await tab.capabilities.get('cdp');await c.send('Network.enable');let cur=(await c.readEvents({methods:['Network.responseReceived','Network.loadingFinished','Network.loadingFailed']})).cursor;
 if(submitSearch) await submitSearch(); else {await tab.playwright.locator('#search-input').fill(q); await tab.playwright.locator('#search-input').press('Enter');}
 let id=null,finished=new Set(),failed=new Set();
 for(let n=0;n<12&&!(id&&finished.has(id));n++){
  const ev=await c.readEvents({afterSequence:cur,methods:['Network.responseReceived','Network.loadingFinished','Network.loadingFailed'],timeoutMs:3000,limit:1000});cur=ev.cursor;if(ev.truncated)throw Error('网络事件不完整');
  for(const e of ev.events){let p=e.params||{};if(e.method==='Network.responseReceived'&&p.response?.url?.split('?')[0]==='https://research.ebsco.com/api/search/v1/search'&&p.response.status===200)id=p.requestId;if(e.method==='Network.loadingFinished')finished.add(p.requestId);if(e.method==='Network.loadingFailed')failed.add(p.requestId)}
  if(id&&failed.has(id))throw Error('上游搜索请求失败');
 }
 if(!id||!finished.has(id))throw Error('未收到完整搜索响应');const raw=await c.send('Network.getResponseBody',{requestId:id});if(raw.base64Encoded||typeof raw.body!=='string')throw Error('无法读取上游响应');
 let s=JSON.parse(raw.body).search;
 if(!s||s.query!==q||!Array.isArray(s.items)||s.items.some(x=>x.shortDbName!=='ahr')||!Number.isInteger(s.totalItems))throw Error('关键词或数据库范围不匹配，拒绝返回');
 let state=await tab.playwright.evaluate(()=>({url:location.href,db:document.querySelector('[data-auto="selected-databases-button"]')?.innerText||'',q:document.querySelector('#search-input')?.value||''}));let u=new URL(state.url);
 if(u.hostname!=='research.ebsco.com'||u.searchParams.get('db')!=='ahr'||state.q.trim()!==q)throw Error('当前页面数据库或关键词不一致');
 return {source:'EBSCO Nursing and Allied Health Reference Source',query:q,total:s.totalItems,items:s.items.slice(0,limit).map(x=>({id:x.id,accession:x.an,database:x.longDbName,title_raw:x.title?.value,date:x.publicationDate,source:x.source,authors:x.contributors?.map(z=>z.name),type:x.docTypeDisplayNames})),note:'通过已认证会话捕获一次首屏检索响应，标题保留上游高亮HTML；全文、分页、零结果及第三方AI使用许可未验证，医学条目不替代专业诊断。'};
}
